function render() {
  const out = [];
  out.push('007 — COMPLETE WEBSITE TEXT EXTRACTION · see you in laos.');
  out.push('Every guest-facing word of the current production source (main ' + execFileSync('git', ['rev-parse', '--short', 'HEAD'], { cwd: ROOT }).toString().trim() + '), extracted ' + new Date().toISOString() + ' from ' + ORIGIN);
  out.push('Method: each active route rendered in a browser (Worker API mocked, no production write), the live DOM walked in document order —');
  out.push('text nodes, [aria-label], [alt], [title], [placeholder], [value] — with "(hidden)" marking text that is in the page but not shown until an interaction;');
  out.push('every reachable state rendered and dumped for its surface; the generated Review & Send text, the seat-confirmation PDFs (read back) and the');
  out.push('string literals of every script that reaches a guest are included. Nothing is summarised, corrected, shortened or deduplicated across surfaces.');
  out.push('Access codes never appear: [SECRET OMITTED] / [SECRET ACCESS CODE OMITTED] stand where a code would be typed or shown.');
  out.push('');
  for (const s of sections) {
    out.push('============================================================');
    out.push('PAGE / SURFACE: ' + s.surface);
    out.push('============================================================');
    out.push('');
    out.push('SOURCE:');
    out.push(s.source);
    out.push('');
    if (s.generatedBy) { out.push('GENERATED BY:'); out.push(s.generatedBy); out.push(''); }
    out.push('STATE:');
    out.push(s.state);
    out.push('');
    out.push('TEXT:');
    out.push('');
    for (const l of s.lines) out.push(l);
    out.push('');
  }
  return out.join('\n') + '\n';
}

/* ------------------------------------------------------------------ the DOM walk (runs in the page) */
const DUMP = `(function (rootSel, opts) {
  opts = opts || {};
  var root = rootSel === 'html' ? document.documentElement : document.querySelector(rootSel);
  if (!root) return ['[no element ' + rootSel + ']'];
  var lines = [], cur = [];
  var BLOCK = /^(ADDRESS|ARTICLE|ASIDE|BLOCKQUOTE|BUTTON|DD|DETAILS|DIALOG|DIV|DL|DT|FIELDSET|FIGCAPTION|FIGURE|FOOTER|FORM|H1|H2|H3|H4|H5|H6|HEADER|HR|LEGEND|LI|MAIN|NAV|OL|OPTION|P|PRE|SECTION|SUMMARY|TABLE|TBODY|TD|TFOOT|TH|THEAD|TR|UL|TEXTAREA|SELECT|INPUT|SVG|G|TEXT|LABEL|TITLE)$/;
  function flush() { var t = cur.join('').replace(/\\s+/g, ' ').trim(); if (t) lines.push(t); cur = []; }
  function hiddenOf(el) {
    try { if (el.hidden || el.getAttribute('hidden') !== null) return true; var cs = getComputedStyle(el); if (cs.display === 'none' || cs.visibility === 'hidden') return true; } catch (e) {}
    return false;
  }
  function walk(node, hidden) {
    for (var i = 0; i < node.childNodes.length; i++) {
      var n = node.childNodes[i];
      if (n.nodeType === 3) { var t = n.textContent.replace(/\\s+/g, ' '); if (t.trim()) cur.push((hidden && !cur.length ? '(hidden) ' : '') + t); continue; }
      if (n.nodeType !== 1) continue;
      var tag = n.tagName.toUpperCase();
      if (tag === 'BR') { cur.push(' '); continue; }
      if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'NOSCRIPT' || tag === 'LINK' || tag === 'META' || tag === 'HEAD') continue;   /* the head is read once, below */
      var h = hidden || hiddenOf(n);
      var pre = h ? '(hidden) ' : '';
      var attrs = [];
      ['aria-label', 'alt', 'title', 'placeholder', 'aria-placeholder', 'aria-valuetext', 'aria-roledescription'].forEach(function (a) { var v = n.getAttribute && n.getAttribute(a); if (v && v.trim()) attrs.push('[' + a + '] ' + v.replace(/\\s+/g, ' ').trim()); });
      if (tag === 'INPUT' && /^(button|submit|reset)$/i.test(n.type) && n.value) attrs.push('[value] ' + n.value);
      var st = [];
      if (n.getAttribute('aria-pressed') === 'true') st.push('pressed'); if (n.getAttribute('aria-current')) st.push('current'); if (n.getAttribute('aria-expanded') === 'true') st.push('expanded');
      if (n.getAttribute('aria-selected') === 'true') st.push('selected'); if (n.getAttribute('aria-disabled') === 'true' || n.disabled) st.push('disabled'); if (tag === 'INPUT' && /^(checkbox|radio)$/i.test(n.type) && n.checked) st.push('checked');
      if (n.getAttribute('aria-live')) st.push('live region · ' + n.getAttribute('aria-live')); if (n.getAttribute('role') === 'status' || n.getAttribute('role') === 'alert') st.push(n.getAttribute('role'));
      if (st.length) attrs.push('[state] ' + st.join(' · '));
      if (tag === 'IMG' && !n.getAttribute('alt') && n.getAttribute('alt') !== '') attrs.push('[img without alt] ' + (n.getAttribute('src') || '').split('/').pop());
      var block = BLOCK.test(tag) || (n.ownerSVGElement && tag === 'G');
      if (!block && !h) { try { var d = getComputedStyle(n).display; if (d && d !== 'inline' && d !== 'inline-block' && d !== 'contents') block = true; } catch (e) {} }
      if (block) flush();
      attrs.forEach(function (a) { if (block) lines.push(pre + a); else cur.push(' ' + pre + a + ' '); });
      if (tag === 'TEMPLATE') { walk(n.content, h); continue; }
      walk(n, h);
      if (block) flush();
    }
  }
  function walkHead(head) {
    var t = head.querySelector('title'); if (t && t.textContent.trim()) lines.push('[page title] ' + t.textContent.trim());
    var d = head.querySelector('meta[name="description"]'); if (d && d.content) lines.push('[meta description] ' + d.content.trim());
  }
  if (rootSel === 'html') walkHead(document.head);
  walk(root, hiddenOf(root));
  flush();
  return lines;
})`;

/* ------------------------------------------------------------------ the mocked Worker */
const mock = { status: null, seating: 'closed', holds: {}, frozen: false, register: 'ok', inventory: 'ok', registered: [] };
const view = (inv) => { const mine = { ceremony: {}, dinner: {} };
  const dress = (s, ev) => { const h = mock.holds[ev + ':' + s.seatId]; const row = { seatId: s.seatId, family: false, state: h ? (h.inv === inv ? 'yours' : 'taken') : 'available' }; if (row.state === 'yours') { row.guestId = h.guestId; row.allocated = h.state === 'allocated'; mine[ev][h.guestId] = s.seatId; } return row; };
  return { ok: true, open: true, frozen: mock.frozen, configured: { ceremony: true, dinner: true }, capacity: { ceremony: { guestSeats: 50, left: 20, right: 30, fixed: 2 }, dinner: { guestSeats: 50, top: 25, bottom: 25, totalPeople: 50 } }, mine,
    ceremony: { rows: cfg.ceremony.rows.map((r) => ({ side: r.side, row: r.row, seats: r.seats.map((s) => dress(s, 'ceremony')) })), fixed: ['BRIDE', 'GROOM'] },
    dinner: { sides: { T: cfg.dinner.sides.T.map((s) => dress(s, 'dinner')), B: cfg.dinner.sides.B.map((s) => dress(s, 'dinner')) }, totalPeople: 50 } }; };
async function wire(page) {
  page.on('pageerror', (e) => console.log('   PAGE ERROR', e.message.slice(0, 120)));
  await page.route(WORKER + '/api/**', async (route) => {
    const url = new URL(route.request().url()), json = (status, body) => route.fulfill({ status, contentType: 'application/json', headers: { 'access-control-allow-origin': '*' }, body: JSON.stringify(body) });
    if (route.request().method() === 'OPTIONS') return route.fulfill({ status: 204, headers: { 'access-control-allow-origin': '*', 'access-control-allow-headers': '*' } });
    if (url.pathname === '/api/status') return json(200, mock.status || { ok: true, received: false, receivedAt: null, confirmed: false, confirmedAt: null });
    if (url.pathname === '/api/register') { if (mock.register === 'fail') return json(500, { ok: false }); const b = JSON.parse(route.request().postData() || '{}'); mock.registered.push(b); const at = b.registration && b.registration.registration_submitted_at || new Date().toISOString(); mock.status = { ok: true, received: true, receivedAt: at, confirmed: false, confirmedAt: null }; return json(200, { ok: true, receivedAt: at }); }
    if (url.pathname.startsWith('/api/inventory')) {
      if (url.pathname.endsWith('/reserve') && mock.inventory === 'conflict') return json(409, { ok: false, conflicts: [{ name: 'Shama Yen-Akat · King Studio with balcony', remaining: 0 }] });
      if (route.request().method() === 'POST') return json(200, { ok: true, reserved: [] });
      return json(200, { ok: true, windows: {}, items: {} });
    }
    if (url.pathname.startsWith('/api/seating')) {
      const inv = url.searchParams.get('invitation') || '';
      if (mock.seating === 'closed') { if (route.request().method() === 'POST') return json(423, { ok: false, error: 'seating is not open' }); return json(200, { ok: true, open: false, frozen: false, configured: { ceremony: false, dinner: false }, ceremony: null, dinner: null, mine: { ceremony: {}, dinner: {} } }); }
      if (url.pathname.endsWith('/select')) { const q = JSON.parse(route.request().postData() || '{}'); if (mock.frozen) return json(423, { ok: false, error: 'seating is frozen' }); const prev = Object.keys(mock.holds).find((kk) => kk.startsWith(q.event + ':') && mock.holds[kk].inv === q.invitationId && mock.holds[kk].guestId === q.guestId); if (prev && mock.holds[prev].state === 'allocated') return json(423, { ok: false, error: 'allocated by Guest Relations' }); const k = q.event + ':' + q.seatId; const cur = mock.holds[k]; if (cur && !(cur.inv === q.invitationId && cur.guestId === q.guestId)) return json(409, { ok: false, error: 'taken', ...view(q.invitationId) }); for (const kk of Object.keys(mock.holds)) if (kk.startsWith(q.event + ':') && mock.holds[kk].inv === q.invitationId && mock.holds[kk].guestId === q.guestId) delete mock.holds[kk]; mock.holds[k] = { inv: q.invitationId, guestId: q.guestId }; return json(200, { ok: true, ...view(q.invitationId) }); }
      if (url.pathname.endsWith('/release')) { const q = JSON.parse(route.request().postData() || '{}'); for (const kk of Object.keys(mock.holds)) if (kk.startsWith(q.event + ':') && mock.holds[kk].inv === q.invitationId && mock.holds[kk].guestId === q.guestId) delete mock.holds[kk]; return json(200, { ok: true, ...view(q.invitationId) }); }
      return json(200, view(inv));
    }
    return json(404, { ok: false });
  });
}

